24	// (leading slash stripped, remaining slashes replaced with dashes), not MD5.
25	// For example: /private/tmp/foo -> private-tmp-foo.
26	func WorkspaceSlug(projectPath string) string {
27		return strings.ReplaceAll(strings.TrimPrefix(projectPath, "/"), "/", "-")
