	})
	jsonlBuf.Write(metaLine)
	jsonlBuf.WriteByte('\n')
	for _, id := range []string{"blob-a", "blob-b"} {
		line, _ := json.Marshal(map[string]any{
			"t":    "blob",
			"id":   id,
			"data": base64.StdEncoding.EncodeToString(blobContents[id]),
		})
